<template>
  <div class="fx-page">
    <div class="fx-crumb">财务管理 <i>/</i> 汇率历史</div>
    <div class="fx-heading"><div><h1>汇率历史</h1><p>统一方向：1 源币 = X 目标币；已被业务引用的历史版本不可覆盖。</p></div><el-button v-if="$can('finance.account.manage')" type="success" class="green" @click="dialog=true">新增汇率</el-button></div>
    <section class="filter-card"><el-form size="small" class="rate-filter"><el-form-item label="源币"><el-select v-model="query.source_currency" clearable filterable placeholder="请选择源币"><el-option v-for="c in currencies" :key="c.currency_code" :label="c.currency_code" :value="c.currency_code" /></el-select></el-form-item><el-form-item label="目标币"><el-select v-model="query.target_currency" clearable filterable placeholder="请选择目标币"><el-option v-for="c in currencies" :key="c.currency_code" :label="c.currency_code" :value="c.currency_code" /></el-select></el-form-item><el-form-item label="汇率类型"><el-select v-model="query.rate_type" clearable placeholder="请选择汇率类型"><el-option label="业务汇率" value="business"/><el-option label="估值汇率" value="valuation"/><el-option label="实际成交汇率" value="actual_settlement"/></el-select></el-form-item><el-form-item label="生效日期"><el-date-picker v-model="dateRange" type="daterange" value-format="yyyy-MM-dd" start-placeholder="开始日期" end-placeholder="结束日期" @change="syncRange"/></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable placeholder="请选择状态"><el-option label="启用" value="enabled"/><el-option label="停用" value="disabled"/><el-option label="已固化" value="frozen"/></el-select></el-form-item><el-form-item label="来源"><el-select v-model="query.source" clearable placeholder="请选择来源"><el-option label="财务部录入" value="manual"/><el-option label="银行" value="bank"/><el-option label="平台" value="platform"/><el-option label="外部估值" value="external"/></el-select></el-form-item><div class="filter-actions"><el-button class="green" type="success" @click="search">查询</el-button><el-button @click="reset">重置</el-button></div></el-form></section>
    <section class="table-card"><el-table v-loading="loading" :data="rows" border size="small"><el-table-column label="源币" width="88" prop="source_currency"/><el-table-column label="目标币" width="88" prop="target_currency"/><el-table-column label="汇率方向说明" min-width="190"><template slot-scope="{row}">1 {{row.source_currency}} = {{number(row.rate)}} {{row.target_currency}}</template></el-table-column><el-table-column label="汇率类型" min-width="118"><template slot-scope="{row}"><el-tag size="mini" :class="rateType(row)==='actual_settlement'?'actual-tag':''" :type="rateType(row)==='valuation'?'success':''">{{rateLabel(rateType(row))}}</el-tag></template></el-table-column><el-table-column label="生效时间" min-width="118"><template slot-scope="{row}">{{date(row.effective_at)}}</template></el-table-column><el-table-column label="来源" min-width="120"><template slot-scope="{row}">{{sourceLabel(row)}}</template></el-table-column><el-table-column label="状态" width="90"><template slot-scope="{row}"><el-tag size="mini" :type="row.status==='enabled'?'success':row.status==='frozen'?'info':'danger'">{{statusLabel(row.status)}}</el-tag></template></el-table-column><el-table-column label="已被业务引用" min-width="115"><template slot-scope="{row}"><el-link v-if="row.record_type==='actual_settlement'" type="primary" @click="$router.push(`/finance/transfers/${row.source_document_id}`)">查看 {{row.source_document_no}}</el-link><span v-else :class="Number(row.business_reference_count||0)>0?'used':''">{{Number(row.business_reference_count||0)>0 ? `是（${row.business_reference_count}）` : '否（0）'}}</span></template></el-table-column><el-table-column label="创建时间" min-width="145"><template slot-scope="{row}">{{dateTime(row.created_at)}}</template></el-table-column><el-table-column label="操作" width="112"><template slot-scope="{row}"><el-button v-if="row.record_type==='rate_master'" type="text">查看</el-button><el-button v-if="row.record_type==='rate_master' && row.status==='enabled' && $can('finance.account.manage')" type="text" class="danger" @click="disable(row)">停用</el-button><el-button v-else-if="row.record_type==='actual_settlement'" type="text" @click="$router.push(`/finance/transfers/${row.source_document_id}`)">查看来源</el-button></template></el-table-column></el-table><el-pagination background layout="total, sizes, prev, pager, next, jumper" :total="total" :current-page="page" :page-size="perPage" :page-sizes="[10,20,50,100]" @current-change="p=>{page=p;load()}" @size-change="s=>{perPage=s;page=1;load()}"/></section>
    <el-dialog title="新增汇率版本" :visible.sync="dialog" width="560px" :close-on-click-modal="false"><el-alert title="已被正式业务引用的历史汇率不会被编辑覆盖；后续变化请新增版本。" type="info" :closable="false" show-icon/><el-form ref="rate" :model="form" :rules="rules" label-width="120px" class="rate-form"><el-form-item label="源币" prop="source_currency"><el-select v-model="form.source_currency" filterable><el-option v-for="c in currencies" :key="c.currency_code" :label="`${c.currency_code} · ${c.currency_name}`" :value="c.currency_code"/></el-select></el-form-item><el-form-item label="目标币" prop="target_currency"><el-select v-model="form.target_currency" filterable><el-option v-for="c in currencies" :key="c.currency_code" :label="`${c.currency_code} · ${c.currency_name}`" :value="c.currency_code"/></el-select></el-form-item><el-form-item label="汇率类型" prop="rate_type"><el-radio-group v-model="form.rate_type"><el-radio label="business">业务汇率</el-radio><el-radio label="valuation">估值汇率</el-radio></el-radio-group></el-form-item><el-form-item label="1 源币 =" prop="rate"><el-input v-model.trim="form.rate"><template slot="append">目标币</template></el-input></el-form-item><el-form-item label="生效日期" prop="effective_at"><el-date-picker v-model="form.effective_at" type="date" value-format="yyyy-MM-dd"/></el-form-item><el-form-item label="备注"><el-input v-model.trim="form.remark" type="textarea" :rows="3"/></el-form-item></el-form><span slot="footer"><el-button @click="dialog=false">取消</el-button><el-button class="green" type="success" :loading="saving" @click="save">保存新版本</el-button></span></el-dialog>
  </div>
</template>
<script>
import { listExchangeRateHistory, listFinanceCurrencies, createExchangeRate, disableExchangeRate } from '../../../api/erp/finance'
const blank=()=>({source_currency:'USD',target_currency:'CNY',rate_type:'business',source:'manual',rate:'',effective_at:new Date().toISOString().slice(0,10),remark:''})
export default {data:()=>({loading:false,saving:false,dialog:false,rows:[],currencies:[],page:1,perPage:20,total:0,dateRange:[],query:{source_currency:'',target_currency:'',rate_type:'',status:'',source:'',effective_start:'',effective_end:''},form:blank(),rules:{source_currency:[{required:true,message:'请选择源币',trigger:'change'}],target_currency:[{required:true,message:'请选择目标币',trigger:'change'}],rate_type:[{required:true,message:'请选择类型',trigger:'change'}],rate:[{required:true,message:'请输入汇率',trigger:'blur'}],effective_at:[{required:true,message:'请选择日期',trigger:'change'}]}}),created(){this.bootstrap()},methods:{async bootstrap(){try{const r=await listFinanceCurrencies({per_page:100,status:'enabled'});this.currencies=r.data.data||[]}catch(e){this.$message.error(e.userMessage||'币种加载失败')}this.load()},async load(){this.loading=true;try{const r=await listExchangeRateHistory({...this.query,page:this.page,per_page:this.perPage});this.rows=r.data.data||[];this.total=Number(r.data.total||0)}catch(e){this.$message.error(e.userMessage||'汇率历史加载失败')}finally{this.loading=false}},syncRange(){this.query.effective_start=this.dateRange?.[0]||'';this.query.effective_end=this.dateRange?.[1]||''},search(){this.page=1;this.load()},reset(){this.dateRange=[];this.query={source_currency:'',target_currency:'',rate_type:'',status:'',source:'',effective_start:'',effective_end:''};this.search()},rateType(r){return r.rate_type},rateLabel(v){return ({business:'业务汇率',valuation:'估值汇率',actual_settlement:'实际成交汇率'})[v]||v},statusLabel(v){return ({enabled:'启用',disabled:'停用',frozen:'已固化'})[v]||v},sourceLabel(r){return r.record_type==='actual_settlement'?'换汇成交单':({manual:'财务部录入',bank:'银行',platform:'平台',external:'系统自动获取'})[r.source]||'手工维护'},number(v){return v===null||v===undefined?'—':Number(v).toFixed(4)},date(v){return v?String(v).slice(0,10):'—'},dateTime(v){return v?String(v).replace('T',' ').slice(0,19):'—'},save(){this.$refs.rate.validate(async ok=>{if(!ok)return;if(this.form.source_currency===this.form.target_currency)return this.$message.error('源币与目标币不能相同');this.saving=true;try{await createExchangeRate(this.form);this.$message.success('已新增汇率版本');this.dialog=false;this.form=blank();this.load()}catch(e){this.$message.error(e.userMessage||'保存失败')}finally{this.saving=false}})},async disable(row){try{await this.$confirm('停用后新业务将不能引用该汇率，历史事实不受影响。','确认停用',{type:'warning'});await disableExchangeRate(row.record_id);this.$message.success('已停用');this.load()}catch(e){if(e!=='cancel')this.$message.error(e.userMessage||'停用失败')}}}}
</script>
<style scoped>
.fx-page{padding:26px 24px 38px;min-height:calc(100vh - 64px);background:#fff;box-sizing:border-box}.fx-crumb{font-size:14px;color:#647187;margin-bottom:22px}.fx-crumb i{font-style:normal;margin:0 9px;color:#b5c0cf}.fx-heading{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:22px}.fx-heading h1{margin:0 0 8px;font-size:26px;line-height:1;color:#121d33}.fx-heading p{margin:0;color:#718099;font-size:14px}.green{background:#078948;border-color:#078948;min-width:116px}.filter-card,.table-card{background:#fff;border:1px solid #e2e8f0;border-radius:7px;box-shadow:0 3px 11px rgba(16,24,40,.035)}.filter-card{padding:20px 24px;margin-bottom:12px}.rate-filter{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px 32px}.rate-filter .el-form-item{margin:0;display:flex;flex-direction:column}.rate-filter .el-form-item__label{height:auto;line-height:20px;text-align:left;color:#36445e;padding:0 0 8px}.rate-filter .el-select,.rate-filter .el-date-editor{width:100%}.filter-actions{grid-column:3 / span 2;align-self:end;display:flex;gap:12px}.table-card{padding:14px 14px 12px;overflow:hidden}.table-card .el-pagination{margin-top:18px;text-align:right}.table-card :deep(.el-table th){background:#f7f9fc;color:#34425b;font-weight:600}.actual-tag{color:#7b4de5!important;border-color:#d6c7fa!important;background:#f7f2ff!important}.used{color:#e84b4b}.rate-form{margin-top:20px}.rate-form .el-select,.rate-form .el-date-editor{width:100%}@media(max-width:1100px){.rate-filter{grid-template-columns:repeat(2,minmax(0,1fr))}.filter-actions{grid-column:auto}.table-card{overflow-x:auto}.table-card .el-table{min-width:1250px}}@media(max-width:600px){.fx-page{padding:18px 14px}.fx-heading{gap:12px;flex-direction:column}.fx-heading .el-button{align-self:flex-start}.rate-filter{grid-template-columns:1fr}.filter-actions{grid-column:auto}}
</style>
